        d = words_to_number(m2.group(1)) if m2.group(1).strip() else 0.0
        c = words_to_number(m2.group(2).replace("and", " ")) if m2.group(2).strip() else 0.0
        return None if d is None or c is None or c >= 100 else d + c / 100.0
