            d = digits(toks[i + 1])
            if len(d) != 1:
                return ""
            out += d * n
            i += 2
            continue
        if w.isdigit():
            out += w
        elif w in _UNITS and _UNITS[w] < 10:
            out += str(_UNITS[w])
        elif w in _TENS:
