def _day_of(toks):
    """The day of the month in tokens: 'twenty sixth', '26', 'twenty six', 'sixth'. None if there is none."""
    for i, w in enumerate(toks):
        if w in _ORD:
            d = _ORD[w]
            if i > 0 and toks[i - 1] in ("twenty", "thirty"):
